window.QUIZ_BANK['mobile-testing'] = (window.QUIZ_BANK['mobile-testing']||[]).concat([
{id:2501,topic:'mobile-testing',difficulty:'beginner',question:'Which class must your iOS unit test classes subclass when using XCTest?',options:['XCTestSuite','XCTestCase','XCTestRun','XCTestObserver'],answer:1,explanation:'XCTestCase is the base class for all iOS unit test classes. You subclass it and add test methods prefixed with "test" so the XCTest runner discovers and executes them automatically.'},
{id:2502,topic:'mobile-testing',difficulty:'beginner',question:'What is the purpose of the `setUp()` method in an XCTestCase subclass?',options:['Tear down resources after each test','Register the test suite globally','Initialize state before each test method runs','Run all test methods in parallel'],answer:2,explanation:'setUp() is called before every individual test method. It is used to create objects, configure state, or reset conditions so each test starts from a known, clean baseline.'},
{id:2503,topic:'mobile-testing',difficulty:'beginner',question:'What does `tearDown()` do in XCTest?',options:['Asserts that a condition is true','Skips the current test','Releases resources and resets state after each test method','Registers a test observer'],answer:2,explanation:'tearDown() is called after every test method completes. It is the place to release resources, close files, or reset shared state to avoid test pollution between individual test cases.'},
{id:2504,topic:'mobile-testing',difficulty:'intermediate',question:'Which XCTest assertion verifies that two values are equal?',options:['XCTAssertTrue','XCTAssertEqual','XCTAssertNil','XCTAssertThrows'],answer:1,explanation:'XCTAssertEqual(expression1, expression2) checks that both expressions produce the same value. If they differ, the test fails with a message showing the actual values, making debugging easier.'},
{id:2505,topic:'mobile-testing',difficulty:'intermediate',question:'What does `XCTAssertNil` verify?',options:['The expression is not nil','The expression throws an error','The expression evaluates to nil','Two expressions are identical objects'],answer:2,explanation:'XCTAssertNil(expression) passes only when the expression evaluates to nil. It is commonly used to verify that optional return values are absent when an operation produces no result.'},
{id:2506,topic:'mobile-testing',difficulty:'intermediate',question:'Which assertion would you use to verify that a function throws an error in Swift XCTest?',options:['XCTAssertEqual','XCTAssertThrowsError','XCTAssertFalse','XCTAssertNoThrow'],answer:1,explanation:'XCTAssertThrowsError wraps a throwing expression and passes when an error is thrown. You can also inspect the error inside the optional trailing closure to verify its type or properties.'},
{id:2507,topic:'mobile-testing',difficulty:'intermediate',question:'In XCTest, which method do you call to test asynchronous code using expectations?',options:['XCTWaiter.fulfill','wait(for:timeout:)','dispatchGroup.wait','RunLoop.current.run'],answer:1,explanation:'After creating an XCTestExpectation, you call wait(for:timeout:) to block the test until the expectation is fulfilled or the timeout expires, allowing asynchronous callbacks to be tested safely.'},
{id:2508,topic:'mobile-testing',difficulty:'intermediate',question:'How do you create an expectation for async code in XCTest?',options:['expectation(description:)','XCTExpect.create()','addExpectation(name:)','asyncExpect(label:)'],answer:0,explanation:'expectation(description:) creates an XCTestExpectation object. You pass it a human-readable description for debugging. Later you call fulfill() on it from the async callback to signal completion.'},
{id:2509,topic:'mobile-testing',difficulty:'advanced',question:'What is the purpose of `addTeardownBlock` in XCTest?',options:['Registers a cleanup closure executed after the current test method','Schedules a test to be skipped','Adds a performance metric','Registers a UI test observer'],answer:0,explanation:'addTeardownBlock adds a closure that runs during teardown in LIFO order. It is useful for inline resource cleanup within a test method without needing to override tearDown(), improving test readability.'},
{id:2510,topic:'mobile-testing',difficulty:'advanced',question:'Which Swift 5.5+ XCTest API enables testing async/await functions directly without XCTestExpectation?',options:['XCTAsync','waitForExpectations','XCTest async test methods with `async` keyword','XCTExpectAsync'],answer:2,explanation:'From Xcode 13+, test methods can themselves be marked async. XCTest automatically awaits them, allowing you to write await calls directly in test methods without creating expectations manually.'},
{id:2511,topic:'mobile-testing',difficulty:'beginner',question:'Which class is the entry point for UI tests in XCUITest?',options:['XCUIDevice','XCUIElement','XCUIApplication','XCUITestCase'],answer:2,explanation:'XCUIApplication represents the application under test. You call launch() on it to start the app and use it as the root element from which all UI queries begin when writing XCUITest UI tests.'},
{id:2512,topic:'mobile-testing',difficulty:'beginner',question:'What is an XCUIElement in XCUITest?',options:['A performance metric','A proxy object representing a UI element in the running app','A test configuration file','A device simulator reference'],answer:1,explanation:'XCUIElement is a proxy that represents a UI element such as a button, label, or text field inside the application under test. Interactions like tap() and typeText() are performed through this proxy.'},
{id:2513,topic:'mobile-testing',difficulty:'intermediate',question:'Which XCUITest method simulates a user tapping a UI element?',options:['element.press()','element.click()','element.tap()','element.touch()'],answer:2,explanation:'tap() is the XCUITest method that simulates a single finger tap on a UI element. It corresponds to the most common user interaction on a touchscreen and triggers the element\'s action handlers.'},
{id:2514,topic:'mobile-testing',difficulty:'intermediate',question:'How do you enter text into a text field using XCUITest?',options:['textField.sendKeys("text")','textField.setText("text")','textField.typeText("text")','textField.input("text")'],answer:2,explanation:'typeText() simulates keyboard input into a text field. The field must be in focus (tap it first if needed). Internally it sends key events character by character through the system keyboard.'},
{id:2515,topic:'mobile-testing',difficulty:'intermediate',question:'Which XCUIElementQuery method retrieves all matching elements as an array?',options:['element','allElementsBoundByIndex','allElements','matchingElements'],answer:2,explanation:'The `allElementsBoundByIndex` property returns an array of all XCUIElements matched by the query. This lets you iterate, count, or index into matched elements. The property `count` also gives the total.'},
{id:2516,topic:'mobile-testing',difficulty:'intermediate',question:'In XCUITest, how do you locate an element by its accessibility identifier?',options:['app.buttons["Submit"]','app.otherElements.matching(identifier: "loginButton").firstMatch','app.buttons.withIdentifier("loginButton")','app.find(id:"loginButton")'],answer:1,explanation:'XCUIElementQuery supports filtering by accessibilityIdentifier using .matching(identifier:). Setting accessibilityIdentifier in your app code is the most reliable and stable locator strategy in XCUITest.'},
{id:2517,topic:'mobile-testing',difficulty:'intermediate',question:'What does `firstMatch` return in an XCUITest query?',options:['The first element from an array literal','The first matching XCUIElement without loading all matches','All matched elements','The element with the lowest z-order'],answer:1,explanation:'firstMatch is an optimized property that returns the first matched element immediately without evaluating the entire query. It is significantly faster than allElementsBoundByIndex[0] for large view hierarchies.'},
{id:2518,topic:'mobile-testing',difficulty:'intermediate',question:'Which XCUITest locator strategy uses the element\'s text or label as the identifier?',options:['accessibilityIdentifier','accessibilityLabel','staticText predicate','type query'],answer:1,explanation:'Setting accessibilityLabel on a view and then querying by label (e.g. app.buttons["OK"]) is a common XCUITest strategy. Labels are visible to VoiceOver and double as human-readable locators in tests.'},
{id:2519,topic:'mobile-testing',difficulty:'intermediate',question:'How do you query elements by type in XCUITest (e.g., all buttons)?',options:['app.allElements.ofType(.button)','app.buttons','app.elements(ofType: .button)','app.query(type:.button)'],answer:1,explanation:'XCUIApplication provides type-specific query properties like app.buttons, app.textFields, app.staticTexts. These are shorthand for app.descendants(matching: .button) and return XCUIElementQuery objects.'},
{id:2520,topic:'mobile-testing',difficulty:'advanced',question:'What is the recommended way to combine multiple query predicates in XCUITest for precise element targeting?',options:['Chaining .matching() calls or using NSPredicate','Using XPathQuery','Using CSS selectors','Using tag names'],answer:0,explanation:'Chaining .matching(identifier:), .matching(NSPredicate), and type filters narrows the query. NSPredicate allows complex conditions like label contains or value matches, providing flexible and powerful element selection.'},
{id:2521,topic:'mobile-testing',difficulty:'intermediate',question:'What Xcode feature lets you generate XCUITest code by interacting with the simulator?',options:['Instruments recording','Test Recording (UI Test Recording)','SwiftUI Previews','Test Plans'],answer:1,explanation:'Xcode\'s UI Test Recording feature monitors your interactions with a running app in the simulator and automatically generates XCUITest Swift code. It is a useful starting point for writing UI tests quickly.'},
{id:2522,topic:'mobile-testing',difficulty:'intermediate',question:'After recording a UI test in Xcode, what is the recommended next step?',options:['Ship the recorded test as-is','Add assertions and refactor to use stable accessibility identifiers','Delete the recording and write from scratch','Convert to Objective-C'],answer:1,explanation:'Recorded tests often use fragile text-based locators. You should add XCTAssert assertions, refactor queries to use accessibilityIdentifier, and extract repeated logic into helper methods for maintainability.'},
{id:2523,topic:'mobile-testing',difficulty:'beginner',question:'What Xcode feature groups multiple test configurations and test targets into a single file?',options:['Scheme','Test Plans (.xctestplan)','xcconfig','Build Phases'],answer:1,explanation:'Test Plans (.xctestplan files) allow you to define multiple test configurations, select test targets, set environment variables, and configure code coverage—all in one file shareable across the team.'},
{id:2524,topic:'mobile-testing',difficulty:'intermediate',question:'Which Swift testing best practice ensures tests are independent and do not share mutable global state?',options:['Using class-level variables for speed','Resetting state in setUp and tearDown','Sharing a singleton across tests','Running tests sequentially only'],answer:1,explanation:'Resetting or recreating state in setUp/tearDown ensures each test is isolated. Sharing mutable state between tests causes flakiness because test execution order is not guaranteed in XCTest.'},
{id:2525,topic:'mobile-testing',difficulty:'intermediate',question:'What is the "Arrange-Act-Assert" pattern in unit testing?',options:['A Git branching strategy','A three-phase test structure: set up inputs, execute the unit, verify outputs','A CI/CD pipeline pattern','A performance profiling pattern'],answer:1,explanation:'AAA structures tests into three clear phases: Arrange (set up data), Act (call the unit under test), Assert (verify the result). This improves readability and makes it clear what each test is verifying.'},
{id:2526,topic:'mobile-testing',difficulty:'intermediate',question:'In Swift XCTest, what is the purpose of `XCTUnwrap`?',options:['Unwraps an optional and fails the test if it is nil','Asserts two objects are identical','Measures performance','Skips a failing test'],answer:0,explanation:'XCTUnwrap attempts to unwrap an optional and returns the non-optional value. If the optional is nil, it fails the test immediately, avoiding force-unwrap crashes while keeping the test flow readable.'},
{id:2527,topic:'mobile-testing',difficulty:'advanced',question:'Which Swift XCTest API is used to measure performance of a code block?',options:['measure { }','XCTProfile { }','timeMeasure { }','XCPerformance.measure { }'],answer:0,explanation:'measure { } runs the enclosed code block 10 times by default and records timing metrics. Results are compared against a baseline you set in Xcode, failing future runs that exceed the threshold significantly.'},
{id:2528,topic:'mobile-testing',difficulty:'intermediate',question:'In Objective-C XCTest, how do you assert that an expression is true?',options:['XCTAssertTrue(expression, @"message")','NSAssert(expression, @"message")','assert(expression)','STAssertTrue(expression, @"message")'],answer:0,explanation:'XCTAssertTrue(expression, format, ...) is the Objective-C macro that fails the test if the expression is false. The format string is printed in the test report to explain what was expected.'},
{id:2529,topic:'mobile-testing',difficulty:'intermediate',question:'In Objective-C XCTest, which macro verifies that two objects are equal using isEqual:?',options:['XCTAssertIdentical','XCTAssertEqual','XCTAssertEqualObjects','XCTAssertSame'],answer:2,explanation:'XCTAssertEqualObjects uses isEqual: to compare objects, while XCTAssertEqual uses C-style == for scalar values. Using XCTAssertEqualObjects with NSString or custom objects is the correct approach in Objective-C.'},
{id:2530,topic:'mobile-testing',difficulty:'beginner',question:'Which command-line tool is used to manage iOS Simulators from the terminal?',options:['idb','xcrun simctl','ios-sim','simmanager'],answer:1,explanation:'xcrun simctl is Apple\'s command-line interface for managing iOS Simulators. It supports creating, booting, installing apps, taking screenshots, and recording video—essential for CI/CD pipelines without a GUI.'},
{id:2531,topic:'mobile-testing',difficulty:'intermediate',question:'Which xcrun simctl command boots a simulator by its UDID?',options:['xcrun simctl start <UDID>','xcrun simctl launch <UDID>','xcrun simctl boot <UDID>','xcrun simctl run <UDID>'],answer:2,explanation:'`xcrun simctl boot <UDID>` starts a simulator device. The UDID can be found with `xcrun simctl list devices`. After booting you can open Simulator.app to see the device or run it headlessly in CI.'},
{id:2532,topic:'mobile-testing',difficulty:'intermediate',question:'Which xcrun simctl command installs an app bundle on a booted simulator?',options:['xcrun simctl push','xcrun simctl install <UDID> <path>','xcrun simctl deploy','xcrun simctl add'],answer:1,explanation:'`xcrun simctl install <UDID> <path/to/app>` installs an .app bundle on the specified simulator. The simulator must be booted first. This is used in CI pipelines before running automated tests.'},
{id:2533,topic:'mobile-testing',difficulty:'intermediate',question:'How do you take a screenshot with xcrun simctl?',options:['xcrun simctl screenshot booted screenshot.png','xcrun simctl capture booted screenshot.png','xcrun simctl snap <UDID> file.png','xcrun simctl screen <UDID> file.png'],answer:0,explanation:'`xcrun simctl io booted screenshot screenshot.png` captures the current screen. Using "booted" as the device ID targets the currently booted simulator without needing the full UDID—convenient for scripts.'},
{id:2534,topic:'mobile-testing',difficulty:'intermediate',question:'Which xcrun simctl command sends a simulated push notification to the simulator?',options:['xcrun simctl notification','xcrun simctl push <UDID> <bundleID> <payload.json>','xcrun simctl alert','xcrun simctl apns'],answer:1,explanation:'`xcrun simctl push` sends a push notification payload (JSON file) to a running app on the simulator. This lets you test notification handling and deeplink routing without a real APNs connection.'},
{id:2535,topic:'mobile-testing',difficulty:'advanced',question:'Which xcrun simctl command creates a new simulator device?',options:['xcrun simctl new','xcrun simctl create <name> <deviceType> <runtime>','xcrun simctl add','xcrun simctl make'],answer:1,explanation:'`xcrun simctl create "iPhone 15" com.apple.CoreSimulator.SimDeviceType.iPhone-15 com.apple.CoreSimulator.SimRuntime.iOS-17-0` creates a new simulator. You can obtain device type and runtime IDs from `xcrun simctl list`.'},
{id:2536,topic:'mobile-testing',difficulty:'beginner',question:'What is Fastlane in the context of iOS and Android development?',options:['A mobile testing framework','An open-source automation tool for building, testing, and releasing mobile apps','A Firebase analytics SDK','An Xcode plugin for UI testing'],answer:1,explanation:'Fastlane is an open-source tool that automates repetitive tasks like running tests, building apps, managing certificates, and releasing to app stores. It uses Ruby-based "lanes" defined in a Fastfile.'},
{id:2537,topic:'mobile-testing',difficulty:'intermediate',question:'Which Fastlane action captures iOS app screenshots automatically across multiple devices and locales?',options:['deliver','snapshot','pilot','match'],answer:1,explanation:'`snapshot` uses XCUITest under the hood to launch the app on multiple simulators and takes screenshots at defined points. The captured images are organized by device and locale for App Store submission.'},
{id:2538,topic:'mobile-testing',difficulty:'intermediate',question:'Which Fastlane action runs iOS tests using xcodebuild?',options:['gym','deliver','scan','match'],answer:2,explanation:'`scan` is the Fastlane action that wraps xcodebuild to run unit and UI tests. It generates human-readable HTML reports and JUnit XML files suitable for CI systems, and handles simulator lifecycle automatically.'},
{id:2539,topic:'mobile-testing',difficulty:'intermediate',question:'What does the Fastlane `deliver` action do?',options:['Builds the iOS app IPA','Uploads screenshots, metadata, and the binary to App Store Connect','Runs UI tests','Manages code signing certificates'],answer:1,explanation:'`deliver` uploads your app\'s binary (.ipa), screenshots, and App Store metadata to App Store Connect. It can submit for review automatically, replacing manual steps in the App Store submission workflow.'},
{id:2540,topic:'mobile-testing',difficulty:'intermediate',question:'Which Fastlane action handles iOS code signing by storing certificates in a Git repository?',options:['cert','sigh','match','produce'],answer:2,explanation:'`match` implements the codesigning.guide approach: it stores encrypted certificates and provisioning profiles in a private Git repo, ensuring all team members and CI machines use the same signing identities.'},
{id:2541,topic:'mobile-testing',difficulty:'intermediate',question:'Which Fastlane action uploads an Android APK or AAB to Google Play?',options:['screengrab','supply','gradle','appcenter'],answer:1,explanation:'`supply` is the Fastlane action for Google Play. It uploads the APK or AAB, updates store metadata and screenshots, and can promote builds between tracks (internal, alpha, beta, production).'},
{id:2542,topic:'mobile-testing',difficulty:'intermediate',question:'What does the Fastlane `screengrab` action do for Android?',options:['Records a video of the device','Captures automated screenshots on Android emulators using Espresso','Uploads screenshots to Firebase','Takes manual screenshots via ADB'],answer:1,explanation:'`screengrab` automates screenshot capture for Android using Espresso tests. It launches the app on emulators across different locales and device configurations, saving images for Play Store listings.'},
{id:2543,topic:'mobile-testing',difficulty:'advanced',question:'In a Fastlane Fastfile, what is a "lane"?',options:['A network routing path','A named sequence of actions executed together to accomplish a workflow goal','A Git branch','A device pool'],answer:1,explanation:'A lane is a named Ruby block in the Fastfile that groups actions. For example, a "test" lane might run `scan`, a "release" lane might run `gym`, `deliver`, and `slack`. Lanes can call other lanes.'},
{id:2544,topic:'mobile-testing',difficulty:'beginner',question:'What is Firebase Test Lab?',options:['A local Android emulator','A cloud-based testing service that runs tests on real and virtual Android and iOS devices hosted by Google','A Firebase analytics dashboard','A unit testing framework'],answer:1,explanation:'Firebase Test Lab provides access to a large fleet of real and virtual devices hosted in Google data centers. You upload your app and test APK/IPA, and tests run automatically with results available in the Firebase console.'},
{id:2545,topic:'mobile-testing',difficulty:'intermediate',question:'Which command-line tool is used to run tests on Firebase Test Lab?',options:['firebase test run','gcloud firebase test android run','ftl-run','firebase deploy --tests'],answer:1,explanation:'The `gcloud firebase test android run` command (part of Google Cloud SDK) submits an instrumented test or Robo test to Firebase Test Lab. Results, logs, videos, and screenshots are stored in Google Cloud Storage.'},
{id:2546,topic:'mobile-testing',difficulty:'intermediate',question:'What is a "Robo test" in Firebase Test Lab?',options:['A performance test that benchmarks CPU usage','An automated crawler that explores the app UI without needing a written test script','A security vulnerability scanner','A manual test recorded by a human tester'],answer:1,explanation:'Robo test is Firebase Test Lab\'s automated crawler. It uses heuristics and ML to explore the app UI automatically, detecting crashes without requiring any test code—ideal for quick smoke testing.'},
{id:2547,topic:'mobile-testing',difficulty:'intermediate',question:'In Firebase Test Lab, what is a "test matrix"?',options:['A code coverage matrix','A combination of devices, OS versions, and locales against which a test is executed','A network simulation grid','A test dependency map'],answer:1,explanation:'A test matrix defines the set of device and OS version combinations. Firebase Test Lab runs your test on each combination in the matrix in parallel, giving broad coverage quickly across device fragmentation.'},
{id:2548,topic:'mobile-testing',difficulty:'intermediate',question:'Which Firebase Test Lab test type allows running XCUITest or Espresso tests?',options:['Robo test only','Game Loop test only','Instrumentation test','Performance test'],answer:2,explanation:'The Instrumentation test type in Firebase Test Lab runs your own written tests—Espresso for Android or XCUITest for iOS. You provide the app binary and test binary, and Test Lab executes them on real devices.'},
{id:2549,topic:'mobile-testing',difficulty:'advanced',question:'What is a "Game Loop test" in Firebase Test Lab?',options:['A test that loops the game indefinitely','A test type that simulates game player scenarios using a custom intent or URL scheme loop','A multiplayer latency test','A test that records and replays game input'],answer:1,explanation:'Game Loop tests trigger a custom intent (Android) or URL scheme (iOS) that causes the game to execute a simulated scenario automatically. The loop ends when the game signals completion, allowing crash detection.'},
{id:2550,topic:'mobile-testing',difficulty:'beginner',question:'What is AWS Device Farm?',options:['An AWS IoT service','A cloud service for testing Android and iOS apps on real physical devices hosted by Amazon','A mobile app deployment service','A virtual device emulator running on EC2'],answer:1,explanation:'AWS Device Farm provides access to hundreds of real Android and iOS devices in AWS data centers. You upload your app and test scripts to run automated tests or conduct manual remote access sessions.'},
{id:2551,topic:'mobile-testing',difficulty:'intermediate',question:'Which test frameworks does AWS Device Farm support for Android automated testing?',options:['Only Espresso','Espresso, Appium, XCUITest, Calabash, and custom test packages','Only XCUITest','Only Appium'],answer:1,explanation:'AWS Device Farm supports multiple frameworks including Espresso, Appium (Java, Python, Node.js, Ruby), Calabash, and built-in fuzz testing. This flexibility lets teams use their existing automation skills.'},
{id:2552,topic:'mobile-testing',difficulty:'intermediate',question:'What is "remote access" in AWS Device Farm?',options:['Running automated tests without device interaction','Manually interacting with a real device through a browser-based interface in real time','Streaming device logs remotely','Deploying apps remotely via CLI'],answer:1,explanation:'Remote Access lets testers control a real physical device in a browser—tapping, swiping, installing apps, and capturing screenshots in real time. It is useful for exploratory testing and reproducing bugs.'},
{id:2553,topic:'mobile-testing',difficulty:'intermediate',question:'What is a "device pool" in AWS Device Farm?',options:['A group of virtual emulators','A named collection of devices used to run a test run','A set of network profiles','A list of test scripts'],answer:1,explanation:'A device pool is a reusable group of device configurations. You define rules (e.g., platform = Android, OS >= 11) or pick specific devices. A test run is then executed against all devices in the pool in parallel.'},
{id:2554,topic:'mobile-testing',difficulty:'advanced',question:'Which AWS Device Farm feature lets you simulate network conditions like latency, packet loss, and bandwidth throttling?',options:['Device pool rules','Network shaping','Security groups','VPC peering'],answer:1,explanation:'Network shaping in AWS Device Farm allows you to simulate conditions such as 2G, 3G, LTE, or custom packet loss and latency. This is critical for testing app behavior under poor network connectivity.'},
{id:2555,topic:'mobile-testing',difficulty:'beginner',question:'What is BrowserStack App Automate?',options:['A tool for automating browser-based web tests','A cloud platform for running Appium and Espresso tests on real Android and iOS devices','A mobile emulator plugin','A continuous integration server'],answer:1,explanation:'BrowserStack App Automate provides access to thousands of real Android and iOS devices in the cloud. You run Appium, Espresso, or XCUITest scripts against these devices without maintaining your own device lab.'},
{id:2556,topic:'mobile-testing',difficulty:'intermediate',question:'How do you point your Appium test to BrowserStack App Automate?',options:['Change the app package name','Update the Appium server URL to the BrowserStack hub endpoint and add BrowserStack credentials as capabilities','Install the BrowserStack SDK','Use a local proxy only'],answer:1,explanation:'You set the remote WebDriver URL to `https://hub-cloud.browserstack.com/wd/hub` and pass your BrowserStack username/access key plus desired capabilities like device, OS version, and app URL in the session.'},
{id:2557,topic:'mobile-testing',difficulty:'intermediate',question:'What is BrowserStack "App Live"?',options:['A feature for automated test execution','A live interactive session on a real device through the browser for manual testing','A streaming analytics dashboard','An app crash reporter'],answer:1,explanation:'App Live provides real-time interactive access to real iOS and Android devices in the browser. Testers can install apps, interact with them, and validate behavior without owning physical devices.'},
{id:2558,topic:'mobile-testing',difficulty:'intermediate',question:'Which BrowserStack capability specifies the uploaded app to be tested?',options:['"app": "bs://<app_id>"','"bundleId": "com.example.app"','"appPath": "/local/app.apk"','"appURL": "https://app.apk"'],answer:0,explanation:'After uploading an app to BrowserStack via the REST API, you receive an app_id. You set the "app" capability to "bs://<app_id>" so the automation session uses that specific uploaded binary.'},
{id:2559,topic:'mobile-testing',difficulty:'advanced',question:'What is the BrowserStack Local testing feature used for?',options:['Testing apps on local simulators','Establishing a secure tunnel to test apps that connect to localhost or internal staging servers','Downloading device logs','Accessing BrowserStack dashboards offline'],answer:1,explanation:'BrowserStack Local creates an encrypted tunnel between your machine and BrowserStack devices, allowing tests against locally hosted or firewalled servers. You enable it with the "browserstack.local" capability.'},
{id:2560,topic:'mobile-testing',difficulty:'intermediate',question:'What is Sauce Labs\' primary offering for mobile testing?',options:['On-premises device lab software only','A cloud platform providing real devices and emulators/simulators for Appium, Espresso, and XCUITest','A mobile SDK for crash reporting','A CI/CD pipeline tool'],answer:1,explanation:'Sauce Labs provides a cloud of real devices (Sauce Real Device Cloud) and virtual devices (emulators/simulators) for running automated and live mobile tests using Appium, Espresso, and XCUITest.'},
{id:2561,topic:'mobile-testing',difficulty:'intermediate',question:'What is the difference between Sauce Labs\' Real Device Cloud and Virtual Device Cloud?',options:['Real devices run Android only; virtual devices run iOS only','Real Device Cloud uses physical hardware; Virtual Device Cloud uses emulators and simulators','They are identical','Real devices are cheaper'],answer:1,explanation:'Real Device Cloud tests on physical hardware, catching real-world issues like hardware sensors, carrier networks, and OEM customizations. Virtual Device Cloud uses emulators/simulators, which are faster and cheaper.'},
{id:2562,topic:'mobile-testing',difficulty:'intermediate',question:'Which Sauce Labs feature enables live interactive testing on a real device via the browser?',options:['Sauce Insights','Sauce Live Testing','Sauce Connect','Sauce Headless'],answer:1,explanation:'Sauce Live Testing provides a browser-based interface to interact with real devices or virtual devices in real time. It supports manual exploratory testing, debugging, and cross-device compatibility checks.'},
{id:2563,topic:'mobile-testing',difficulty:'advanced',question:'What is "Sauce Connect" in the context of Sauce Labs testing?',options:['An API for uploading apps','A secure tunneling proxy that allows Sauce Labs devices to access locally hosted applications','A browser extension for recording tests','A monitoring agent'],answer:1,explanation:'Sauce Connect establishes an encrypted tunnel between Sauce Labs infrastructure and your private network or localhost. Tests can then reach internal staging environments that are not publicly accessible.'},
{id:2564,topic:'mobile-testing',difficulty:'intermediate',question:'What is Perfecto\'s mobile testing cloud known for?',options:['Free unlimited device access','Enterprise-grade real device testing with security compliance certifications like SOC 2 and ISO 27001','Open-source device management','Local device farm integration only'],answer:1,explanation:'Perfecto is an enterprise testing cloud that emphasizes security compliance, providing SOC 2 Type II and ISO 27001 certified environments. It is popular in regulated industries like banking and healthcare.'},
{id:2565,topic:'mobile-testing',difficulty:'intermediate',question:'Which Perfecto feature provides AI-powered test analysis and flakiness detection?',options:['Perfecto Scriptless','Perfecto Insights','Perfecto Connect','Perfecto Gauge'],answer:1,explanation:'Perfecto Insights uses AI and ML to analyze test results, identify root causes of failures, detect flaky tests, and provide trend analysis. It reduces the time spent manually triaging test failures.'},
{id:2566,topic:'mobile-testing',difficulty:'intermediate',question:'What is Firebase Performance Monitoring used for in mobile testing?',options:['Running unit tests','Collecting real-time performance metrics from production apps to identify slowdowns and bottlenecks','Managing test devices','Crash reporting only'],answer:1,explanation:'Firebase Performance Monitoring automatically collects metrics like app startup time, HTTP request latency, and screen rendering time from real users. Custom traces let you measure specific code paths.'},
{id:2567,topic:'mobile-testing',difficulty:'intermediate',question:'What is a "trace" in Firebase Performance Monitoring?',options:['A log of crash reports','A code segment instrumented to measure the time and resources for a specific operation','A network packet capture','A user session recording'],answer:1,explanation:'A trace wraps a specific block of code. Firebase records how long the trace takes and custom metrics you attach to it. Automatic traces are created for app start, foreground/background transitions, and HTTP calls.'},
{id:2568,topic:'mobile-testing',difficulty:'intermediate',question:'How do you start a custom trace in Firebase Performance Monitoring for Android?',options:['FirebasePerformance.newTrace("name").start()','Trace trace = FirebasePerformance.getInstance().newTrace("name"); trace.start()','PerformanceMonitor.begin("name")','FirebaseTrace.create("name").begin()'],answer:1,explanation:'You obtain an instance with getInstance(), create a named trace with newTrace(), call start() before the operation, and stop() after. Custom metrics and attributes can be added between start and stop.'},
{id:2569,topic:'mobile-testing',difficulty:'advanced',question:'Which Firebase Performance Monitoring feature allows you to filter performance data by app version, device, or country in the console?',options:['Audience segments','Performance attributes and custom attributes','Analytics funnels','A/B testing'],answer:1,explanation:'Performance attributes (built-in like app version, device, OS) and custom attributes you attach to traces allow you to filter and compare performance data in the Firebase console by specific dimensions.'},
{id:2570,topic:'mobile-testing',difficulty:'beginner',question:'What is Android Profiler in Android Studio?',options:['A tool for writing unit tests','An integrated tool for monitoring CPU, memory, network, and energy usage of an Android app in real time','A static code analysis tool','A test runner'],answer:1,explanation:'Android Profiler (formerly DDMS) provides real-time graphs for CPU, memory, network, and energy usage. It helps identify performance bottlenecks, memory leaks, excessive network calls, and battery drain.'},
{id:2571,topic:'mobile-testing',difficulty:'intermediate',question:'What does the CPU Profiler in Android Studio help you identify?',options:['Memory leaks','Slow methods, CPU hotspots, thread activity, and method call traces','Network latency','Database query performance'],answer:1,explanation:'CPU Profiler records method traces or sampled CPU activity to show which methods consume the most CPU time. It visualizes thread timelines and flame charts to pinpoint performance bottlenecks.'},
{id:2572,topic:'mobile-testing',difficulty:'intermediate',question:'What is a "heap dump" in the context of Android Memory Profiler?',options:['A crash report','A snapshot of all objects currently allocated in the app\'s memory heap at a point in time','A CPU trace file','A network packet capture'],answer:1,explanation:'A heap dump captures a snapshot of all live objects in the Java/Kotlin heap. Analyzing it helps find memory leaks—objects that are still referenced but should have been garbage collected.'},
{id:2573,topic:'mobile-testing',difficulty:'intermediate',question:'What does the Network Profiler in Android Studio show?',options:['HTTP response content only','Timing and size of network requests, responses, and payload content','Battery consumption by network activity only','DNS resolution times only'],answer:1,explanation:'Network Profiler displays a timeline of network requests including send/receive timing, payload size, request/response headers, and body content for HTTP calls made through HttpURLConnection or OkHttp.'},
{id:2574,topic:'mobile-testing',difficulty:'advanced',question:'Which Android Profiler feature helps detect memory leaks by tracking object allocations over time?',options:['CPU Trace','Memory Profiler allocation tracking and heap diff analysis','Network Inspector','Energy Profiler'],answer:1,explanation:'Memory Profiler\'s allocation tracking records every object allocation. Comparing heap dumps before and after an action (e.g., navigating back) shows objects that were not collected, identifying leak suspects.'},
{id:2575,topic:'mobile-testing',difficulty:'beginner',question:'What is Xcode Instruments?',options:['A code editor plugin','A suite of performance analysis and testing tools integrated into Xcode for profiling iOS and macOS apps','A build system replacement','An automated test generator'],answer:1,explanation:'Instruments is Apple\'s profiling suite. It includes templates for Time Profiler, Allocations, Leaks, Energy Log, Network, and more—each recording detailed data about the app\'s runtime behavior.'},
{id:2576,topic:'mobile-testing',difficulty:'intermediate',question:'Which Xcode Instruments template is used to find memory leaks in an iOS app?',options:['Time Profiler','Allocations','Leaks','Activity Monitor'],answer:2,explanation:'The Leaks instrument continuously checks for memory leaks while the app runs. It reports leaked objects with their allocation stack trace, making it easier to trace the root cause of retain cycles.'},
{id:2577,topic:'mobile-testing',difficulty:'intermediate',question:'What does the "Time Profiler" template in Instruments measure?',options:['Network request durations','CPU time spent in each method by sampling the call stack at regular intervals','Memory allocation counts','Battery drain'],answer:1,explanation:'Time Profiler samples the call stack at a fixed interval (typically 1ms) to build a statistical profile of where CPU time is spent. The resulting flame graph highlights hot methods and optimisation targets.'},
{id:2578,topic:'mobile-testing',difficulty:'intermediate',question:'Which Instruments template is best for tracking all memory allocations and understanding the growth of heap size over time?',options:['Leaks','Allocations','Time Profiler','Core Data'],answer:1,explanation:'The Allocations template records every object allocation and deallocation, showing heap growth over time. It reveals "abandoned memory" (objects not technically leaked but no longer useful) causing memory growth.'},
{id:2579,topic:'mobile-testing',difficulty:'advanced',question:'What is the "Zombies" template in Xcode Instruments used for?',options:['Finding memory leaks','Detecting use-after-free bugs by converting deallocated objects into zombie objects that trap any further access','Profiling CPU usage','Analyzing network packets'],answer:1,explanation:'Zombies replaces deallocated Objective-C objects with zombie proxies. Any subsequent message sent to a zombie triggers an exception with a full stack trace, pinpointing use-after-free (EXC_BAD_ACCESS) bugs.'},
{id:2580,topic:'mobile-testing',difficulty:'beginner',question:'What is the OWASP Mobile Top 10?',options:['A list of the 10 most popular mobile frameworks','A list of the 10 most critical mobile application security risks as identified by OWASP','The 10 best practices for mobile UI design','A set of 10 performance benchmarks for mobile apps'],answer:1,explanation:'The OWASP Mobile Top 10 documents the most prevalent and impactful security vulnerabilities in mobile apps, guiding developers and testers in prioritizing security efforts for Android and iOS platforms.'},
{id:2581,topic:'mobile-testing',difficulty:'intermediate',question:'Which OWASP Mobile Top 10 category covers sensitive data stored insecurely on the device (e.g., in SharedPreferences or NSUserDefaults in plaintext)?',options:['M1 - Improper Credential Usage','M2 - Inadequate Supply Chain Security','M9 - Insecure Data Storage','M5 - Insecure Communication'],answer:2,explanation:'M9 (Insecure Data Storage, in newer versions) covers sensitive data like passwords and PII stored unencrypted in local files, databases, SharedPreferences, or Keychain with weak access controls, risking data exposure.'},
{id:2582,topic:'mobile-testing',difficulty:'intermediate',question:'Which OWASP Mobile Top 10 risk covers the use of unencrypted network communication?',options:['M3 - Insecure Authentication','M5 - Insecure Communication','M7 - Insufficient Binary Protections','M1 - Improper Credential Usage'],answer:1,explanation:'M5 (Insecure Communication) addresses transmitting sensitive data over plain HTTP or accepting invalid TLS certificates. Attackers on the same network can intercept credentials, tokens, and personal data.'},
{id:2583,topic:'mobile-testing',difficulty:'intermediate',question:'What is MobSF (Mobile Security Framework)?',options:['A mobile performance testing tool','An open-source automated security testing framework that performs static and dynamic analysis of Android and iOS apps','A CI/CD pipeline for mobile apps','A device management platform'],answer:1,explanation:'MobSF is an open-source tool that automates mobile app security testing. Static analysis inspects the binary/source, while dynamic analysis runs the app in an emulator and monitors runtime behavior, network calls, and file system access.'},
{id:2584,topic:'mobile-testing',difficulty:'intermediate',question:'What type of analysis does MobSF perform in "static" mode?',options:['Runtime behavior monitoring','Decompiles the app binary to analyze code, permissions, hardcoded secrets, and misconfigurations without executing it','Network traffic interception','UI interaction automation'],answer:1,explanation:'MobSF static analysis decompiles APKs/IPAs and scans the code for dangerous permissions, hardcoded credentials, insecure API usage, exported components, and known vulnerable patterns without running the app.'},
{id:2585,topic:'mobile-testing',difficulty:'advanced',question:'What is Drozer used for in mobile security testing?',options:['iOS binary analysis','A security assessment framework for Android that lets you interact with exposed IPC endpoints, content providers, and activities','Network packet capture','Automated performance profiling'],answer:1,explanation:'Drozer is an Android security framework that simulates a malicious app to probe an Android device\'s attack surface. It can invoke activities, interact with content providers and broadcast receivers, and exploit insecure IPC.'},
{id:2586,topic:'mobile-testing',difficulty:'intermediate',question:'Which Drozer command lists the attack surface of an Android app by showing exported components?',options:['run app.package.list','run app.package.attacksurface <package>','drozer scan <package>','adb shell dumpsys activity'],answer:1,explanation:'`run app.package.attacksurface <package>` reports how many activities, services, content providers, and broadcast receivers are exported and accessible without permissions, quantifying the app\'s IPC attack surface.'},
{id:2587,topic:'mobile-testing',difficulty:'beginner',question:'What is TalkBack?',options:['A screen recording app for Android','The built-in screen reader accessibility service for Android that provides spoken feedback to visually impaired users','A developer debugging tool','An Android test runner'],answer:1,explanation:'TalkBack is Android\'s screen reader, part of Android Accessibility Suite. It reads out UI element labels, announces state changes, and enables navigation by swipe gestures—essential for blind and low-vision users.'},
{id:2588,topic:'mobile-testing',difficulty:'beginner',question:'What is VoiceOver in the context of iOS accessibility?',options:['An audio playback API','Apple\'s built-in screen reader for iOS that provides spoken descriptions of on-screen elements for visually impaired users','A test automation framework','A voice recognition API'],answer:1,explanation:'VoiceOver is Apple\'s screen reader built into iOS, macOS, tvOS, and watchOS. When enabled, it speaks element labels and hints as users swipe, allowing blind users to navigate apps without seeing the screen.'},
{id:2589,topic:'mobile-testing',difficulty:'intermediate',question:'How should you test TalkBack on an Android device?',options:['Use only automated Espresso tests','Enable TalkBack in Settings > Accessibility, then navigate the app using swipe and double-tap gestures while listening to spoken feedback','Use Android Profiler','Run ADB shell commands only'],answer:1,explanation:'Manual TalkBack testing involves enabling it and using standard gestures: swipe right/left to move between elements, double-tap to activate. Testers verify that all interactive elements have meaningful labels and logical navigation order.'},
{id:2590,topic:'mobile-testing',difficulty:'intermediate',question:'What Android attribute must be set on a View to provide a TalkBack label for an element that lacks descriptive text (e.g., an icon button)?',options:['android:hint','android:contentDescription','android:tag','android:text'],answer:1,explanation:'android:contentDescription provides a text alternative for elements without visible labels. TalkBack reads it aloud when the element is focused. Without it, icon buttons and images are announced without context.'},
{id:2591,topic:'mobile-testing',difficulty:'intermediate',question:'Which XCUITest property reads the accessibilityLabel of an element in iOS UI tests?',options:['element.identifier','element.label','element.accessibilityValue','element.hint'],answer:1,explanation:'The label property on XCUIElement corresponds to the accessibilityLabel set on the UIView. It is also what VoiceOver reads aloud, so tests that verify label values also validate accessibility announcements.'},
{id:2592,topic:'mobile-testing',difficulty:'intermediate',question:'Which UIKit property should be set to make an iOS custom view accessible to VoiceOver?',options:['isHidden = false','isAccessibilityElement = true','accessibilityActivate()','accessibilityFrame'],answer:1,explanation:'Setting isAccessibilityElement = true tells the accessibility system to expose the view as a single accessible element. Without this, a custom-drawn view may be invisible to VoiceOver and assistive technologies.'},
{id:2593,topic:'mobile-testing',difficulty:'intermediate',question:'How can you verify that an iOS element\'s accessibility hint is correct using XCUITest?',options:['element.accessibilityHint == "Expected"','XCTAssertEqual(element.value as? String, "hint")','XCTAssertEqual(app.buttons["Submit"].value as? String, "hint")','element.hint property and XCTAssertEqual'],answer:3,explanation:'XCUIElement\'s .value property maps to accessibilityValue, while the hint is accessible via the .label for hints exposed through accessibility. You can XCTAssertEqual on element properties to assert accessibility attributes in tests.'},
{id:2594,topic:'mobile-testing',difficulty:'advanced',question:'Which Xcode tool audits an iOS app for common accessibility violations programmatically during UI tests?',options:['Accessibility Inspector only','XCUITest with app.performAccessibilityAudit()','Instruments Accessibility template','SimCtl accessibility scan'],answer:1,explanation:'Introduced in Xcode 15, app.performAccessibilityAudit() runs automated accessibility checks during XCUITest execution, detecting issues like missing labels, small touch targets, and low contrast—without manual inspection.'},
{id:2595,topic:'mobile-testing',difficulty:'intermediate',question:'What is the Accessibility Inspector in Xcode used for?',options:['Running automated unit tests','Inspecting accessibility properties of UI elements in the simulator or on a connected device and auditing for issues','Profiling memory usage','Managing provisioning profiles'],answer:1,explanation:'Accessibility Inspector allows developers to inspect accessibilityLabel, hint, value, and traits of every UI element live. Its Audit feature automatically flags missing labels, small touch targets, and color contrast issues.'},
{id:2596,topic:'mobile-testing',difficulty:'beginner',question:'What does WCAG stand for in the context of mobile accessibility?',options:['Web Content Accessibility Guidelines','Wide Coverage Accessibility Graph','Wireless Communication Accessibility Guide','Web Component Accessibility Grammar'],answer:0,explanation:'WCAG (Web Content Accessibility Guidelines) is published by the W3C. While originally designed for web content, its principles—Perceivable, Operable, Understandable, Robust (POUR)—also guide mobile app accessibility design.'},
{id:2597,topic:'mobile-testing',difficulty:'intermediate',question:'Which WCAG success criterion requires that interactive UI elements have a minimum touch target size?',options:['1.4.3 Contrast Minimum','2.5.5 Target Size (AAA) and 2.5.8 Target Size Minimum (AA in WCAG 2.2)','1.1.1 Non-text Content','4.1.2 Name, Role, Value'],answer:1,explanation:'WCAG 2.5.5 requires touch targets to be at least 44×44 CSS pixels (AAA), and WCAG 2.2 adds 2.5.8 at AA level with 24×24 minimum. Small targets are a common mobile accessibility barrier for users with motor impairments.'},
{id:2598,topic:'mobile-testing',difficulty:'intermediate',question:'Which WCAG success criterion (1.4.3) specifies the minimum color contrast ratio for normal text?',options:['3:1','4.5:1','7:1','2:1'],answer:1,explanation:'WCAG 1.4.3 (AA) requires a contrast ratio of at least 4.5:1 for normal text and 3:1 for large text (18pt or 14pt bold). Sufficient contrast ensures text is readable for users with low vision or color blindness.'},
{id:2599,topic:'mobile-testing',difficulty:'intermediate',question:'What does WCAG success criterion 4.1.2 "Name, Role, Value" require for mobile UI components?',options:['All UI must use system fonts','Every user interface component must have a name and role that can be determined programmatically, and state/value must be available to assistive technologies','Touch targets must be 44pt','Navigation must be keyboard-operable'],answer:1,explanation:'4.1.2 ensures that assistive technologies can determine what a component is (role), what it is called (name), and its current state (value). For mobile, this means correct contentDescription, accessibilityLabel, and trait settings.'},
{id:2600,topic:'mobile-testing',difficulty:'advanced',question:'Which WCAG principle does "ensuring an app can be navigated without relying solely on color to convey information" fall under?',options:['Perceivable','Operable','Understandable','Robust'],answer:0,explanation:'The Perceivable principle requires that information is presentable in ways users can perceive. Using color alone to convey meaning fails users who are color blind; additional indicators like icons or text are required under 1.4.1 Use of Color.'}
]);
